import { types, flow, Instance } from 'mobx-state-tree';
import { EmployeeModel } from './employeeModel';
import * as api from '../utils/api';

const RootStore = types
    .model('RootStore', {
        employees: types.array(EmployeeModel)
    })
    .actions(self => {
        const fetchEmployees = flow(function* () {
            try {
                const data = yield api.fetchEmployees();
                self.employees.clear();
                data.forEach((e: any) =>
                    self.employees.push({
                        id: e.id ?? e._id ?? '',
                        firstName: e.firstName ?? '',
                        lastName: e.lastName ?? '',
                        position: e.position ?? '',
                        currentHourlyRate: e.currentHourlyRate ?? 0,
                        salaryHistory: (e.salaryHistory ?? []).map((s: any) => ({
                            hourlyRate: s.hourlyRate,
                            effectiveFrom: s.effectiveFrom
                        })),
                        hireDate: e.hireDate ?? null,
                        isActive: e.isActive ?? true
                    } as any)
                );
            } catch (err) {
                console.error(err);
            }
        });

        const addEmployee = flow(function* (payload: any) {
            try {
                yield api.createEmployee(payload);
                yield fetchEmployees();
            } catch (err) {
                throw err;
            }
        });

        return { fetchEmployees, addEmployee };
    });

export function createRootStore() {
    const s = RootStore.create({ employees: [] as any });
    (s as any).fetchEmployees();
    return s;
}

export type RootStore = Instance<typeof RootStore>;