import React, { useEffect, useState } from 'react';
import { Card, Callout, Button } from '@blueprintjs/core';
import EmployeeForm from './EmployeeForm';
import EmployeeGrid from './EmployeeGrid';
import { useStore } from '../stores/useStore';

const EmployeeList: React.FC = () => {
    const store = useStore();
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        (async () => {
            setLoading(true);
            try {
                await (store as any).fetchEmployees();
                setError(null);
            } catch (err: any) {
                setError(err?.message ?? '������ ��� �������� �����������');
            } finally {
                setLoading(false);
            }
        })();
    }, [store]);

    return (
        <div>
            <Card style={{ marginBottom: 12 }}>
                <h4>�������� ����������</h4>
                <EmployeeForm
                    onSubmit={async values => {
                        setLoading(true);
                        try {
                            await (store as any).addEmployee(values);
                            setError(null);
                        } catch (err: any) {
                            setError(err?.message ?? '������ ��� �������� ����������');
                        } finally {
                            setLoading(false);
                        }
                    }}
                />
            </Card>

            <Card>
                <h4>������ �����������</h4>

                {error && (
                    <Callout intent="danger" style={{ marginBottom: 12 }}>
                        <div>{error}</div>
                        <div style={{ marginTop: 8 }}>
                            <Button minimal onClick={async () => {
                                setLoading(true);
                                setError(null);
                                try { await (store as any).fetchEmployees(); }
                                catch (e: any) { setError(e?.message ?? '������ ��� ��������'); }
                                finally { setLoading(false); }
                            }}>���������</Button>
                        </div>
                    </Callout>
                )}

                {loading ? <div>��������...</div> : <EmployeeGrid rows={(store as any).employees.slice()} />}
            </Card>
        </div>
    );
};

export default EmployeeList;