import React from 'react';
import { Formik, Form, Field, ErrorMessage } from 'formik';
import * as Yup from 'yup';
import { Button, InputGroup } from '@blueprintjs/core';

const Schema = Yup.object().shape({
    firstName: Yup.string().required('�����������'),
    lastName: Yup.string().required('�����������'),
    position: Yup.string().required('�����������'),
    initialHourlyRate: Yup.number().min(0, '>= 0').nullable()
});

type Props = {
    onSubmit: (values: any) => Promise<void>;
};

const EmployeeForm: React.FC<Props> = ({ onSubmit }) => (
    <Formik
        initialValues={{ firstName: '', lastName: '', position: '', initialHourlyRate: '', initialEffectiveFrom: '' }}
        validationSchema={Schema}
        onSubmit={async (values, { resetForm }) => {
            const payload: any = { firstName: values.firstName, lastName: values.lastName, position: values.position };
            if (values.initialHourlyRate !== '') payload.initialHourlyRate = Number(values.initialHourlyRate);
            if (values.initialEffectiveFrom) payload.initialEffectiveFrom = values.initialEffectiveFrom;
            await onSubmit(payload);
            resetForm();
        }}
    >
        {({ isSubmitting }) => (
            <Form>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
                    <div>
                        <label>���</label>
                        <Field name="firstName" as={InputGroup} />
                        <div style={{ color: 'red' }}>
                            <ErrorMessage name="firstName" />
                        </div>
                    </div>
                    <div>
                        <label>�������</label>
                        <Field name="lastName" as={InputGroup} />
                        <div style={{ color: 'red' }}>
                            <ErrorMessage name="lastName" />
                        </div>
                    </div>
                    <div>
                        <label>���������</label>
                        <Field name="position" as={InputGroup} />
                        <div style={{ color: 'red' }}>
                            <ErrorMessage name="position" />
                        </div>
                    </div>
                    <div>
                        <label>��������� ������</label>
                        <Field name="initialHourlyRate" as={InputGroup} />
                    </div>
                    <div>
                        <label>���� ������ ������ (ISO)</label>
                        <Field name="initialEffectiveFrom" as={InputGroup} placeholder="2024-01-01T00:00:00Z" />
                    </div>
                    <div style={{ alignSelf: 'end' }}>
                        <Button type="submit" intent="primary" loading={isSubmitting}>
                            ��������
                        </Button>
                    </div>
                </div>
            </Form>
        )}
    </Formik>
);

export default EmployeeForm;