import { types } from 'mobx-state-tree';

export const SalaryEntryModel = types.model('SalaryEntry', {
    hourlyRate: types.number,
    effectiveFrom: types.string
});

export const EmployeeModel = types.model('Employee', {
    id: types.identifier,
    firstName: types.string,
    lastName: types.string,
    position: types.string,
    currentHourlyRate: types.number,
    salaryHistory: types.array(SalaryEntryModel),
    hireDate: types.maybeNull(types.string),
    isActive: types.boolean
});

export type EmployeeModelType = typeof EmployeeModel.Type;